// FlowKit landing page. All numbers come from benchmark-data.js, generated by `npm run benchmark`.
const data = window.FLOWKIT_BENCHMARK || null;
const $ = (selector) => document.querySelector(selector);
const fmt = (n) => Math.round(n).toLocaleString("en-US");
const compact = (n) => (n >= 1000 ? `${(n / 1000).toFixed(1)}K` : String(n));
const ms = (n) => (n < 100 ? `${n.toFixed(1)} ms` : `${fmt(n)} ms`);
const esc = (s) => String(s ?? "").replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]);
const short = (name) => name.replace(/^flowkit_/, "");

// ── Copy buttons ──
function copyButton(button, getText) {
  if (!button) return;
  button.addEventListener("click", async () => {
    const label = button.textContent;
    try {
      await navigator.clipboard.writeText(getText());
      button.textContent = "Copied"; button.classList.add("copied");
    } catch { button.textContent = "Select the text to copy"; }
    setTimeout(() => { button.textContent = label; button.classList.remove("copied"); }, 1800);
  });
}

// ── Tabbed terminals (install, testing, clients) ──
function terminal({ items, attr, code, label, note, copy, docs, initial }) {
  let active = initial;
  const show = (name) => {
    const item = items[name]; if (!item || !code) return;
    active = name;
    code.textContent = item.command;
    if (label) label.textContent = item.label;
    if (note) note.textContent = item.note;
    if (docs && item.docs) docs.href = item.docs;
    document.querySelectorAll(`[${attr}]`).forEach((tab) => tab.setAttribute("aria-selected", String(tab.getAttribute(attr) === name)));
  };
  document.querySelectorAll(`[${attr}]`).forEach((tab) => tab.addEventListener("click", () => show(tab.getAttribute(attr))));
  // Sample output shows "$ command"; copy only the commands.
  copyButton(copy, () => {
    const text = items[active].command;
    const prompts = text.split("\n").filter((line) => line.startsWith("$ "));
    return prompts.length ? prompts.map((line) => line.slice(2)).join("\n") : text;
  });
  show(initial);
}

terminal({
  attr: "data-install", initial: "global", code: $("#install-command"), label: $("#install-label"), note: $("#install-note"), copy: $("#copy-install"),
  items: {
    global: { label: "Global npm install", note: "Installs the flowkit-mcp command on your PATH",
      command: "npm install --global flowkit-mcp\nflowkit-mcp --doctor --workspace /path/to/files" },
    npx: { label: "Run without installing", note: "Downloads on first use; needs Node.js 22.12+",
      command: "npx -y flowkit-mcp --doctor --workspace /path/to/files\n\n# In MCP client configs use:\n#   command: npx   args: [\"-y\", \"flowkit-mcp\", \"--workspace\", \"/path/to/files\"]" },
    source: { label: "Clone and run from source", note: "For development and custom tools",
      command: "git clone https://github.com/ayusht9/Flowkit.git\ncd Flowkit\nnpm install\nnode mcp-server.mjs --doctor --workspace /path/to/files" },
    engines: { label: "Install native engines", note: "Install only what you need; --doctor shows what is missing",
      command: "# macOS (Homebrew)\nbrew install pandoc qpdf ghostscript imagemagick ffmpeg\n\n# Ubuntu / Debian\nsudo apt-get install pandoc qpdf ghostscript imagemagick ffmpeg\n\n# Windows (winget)\nwinget install JohnMacFarlane.Pandoc QPDF.QPDF ArtifexSoftware.GhostScript ImageMagick.ImageMagick Gyan.FFmpeg" },
  },
});

const passedLine = data?.latency ? `${data.summary.toolsPassed} passed, ${data.summary.toolsSkipped} skipped, ${data.summary.toolsFailed} failed` : "";
terminal({
  attr: "data-test", initial: "doctor", code: $("#test-command"), label: $("#test-label"), note: $("#test-note"), copy: $("#copy-test"),
  items: {
    doctor: { label: "Health check", note: "Confirms the CLI, workspace, and each native engine",
      command: `$ flowkit-mcp --doctor --workspace /path/to/files\nFlowKit MCP ${data?.environment.flowkitVersion ?? ""}: installed\nWorkspace: /path/to/files\n` +
        (data ? Object.entries(data.environment.engines).map(([name, version]) => `${name}: ${version === "not installed" ? "missing" : `ready - ${name} ${version}`}`).join("\n") : "") + "\nProcessing tools: ready" },
    benchmark: { label: "Full benchmark", note: "Runs every tool on real files and regenerates the report",
      command: `$ npm run benchmark\n\nAverage: ${data?.summary.averageSavedTokens ?? "—"} tokens saved per task (${data?.summary.averageReductionPercent ?? "—"}%).\nWorkflows: ${data?.summary.workflowReduction.join("–") ?? "—"}% fewer.\nTool list: ${data ? fmt(data.summary.allToolsFixedTokens) : "—"} tokens (all) / ~${data ? fmt(data.summary.oneToolsetFixedTokens) : "—"} (one group).\nTools: ${passedLine} of ${data?.summary.toolsRun ?? "—"}.\nBoundaries blocked: ${data?.summary.boundariesBlocked ?? "—"}.` },
    suite: { label: "Automated tests", note: "Native-engine tests skip with a reason when an engine is missing",
      command: "$ npm test\n\n✔ MCP stdio discovers tools, chains artifacts and returns bounded text\n✔ MCP toolsets limit advertised tools and keep compact schemas valid\n✔ MCP rejects path escapes, symlinks outside the workspace, invalid options\n✔ MCP uses real Pandoc, ImageMagick and FFmpeg for every native processing tool\n✔ MCP reads credentials and signature attachments from workspace paths\n✔ qpdf extracts and reorders actual pages, merges in input order\n…\nℹ tests 127\nℹ pass 125\nℹ fail 0\nℹ skipped 2" },
    inspector: { label: "MCP Inspector", note: "Browse and call tools interactively",
      command: "npx @modelcontextprotocol/inspector flowkit-mcp --workspace /path/to/files" },
  },
});

const config = (key, extra = "") => `{\n  "${key}": {\n    "flowkit": {${extra}\n      "command": "flowkit-mcp",\n      "args": ["--workspace", "/path/to/files", "--tools", "all"]\n    }\n  }\n}`;
terminal({
  attr: "data-client", initial: "claude", code: $("#client-command code"), label: $("#client-label"), note: $("#client-note"), copy: $("#copy-client"), docs: $("#client-docs"),
  items: {
    claude: { label: "Claude Code", note: "Verify with: claude mcp list", docs: "https://code.claude.com/docs/en/mcp",
      command: "claude mcp add --transport stdio flowkit -- flowkit-mcp --workspace /path/to/files\n\n# Only PDF and image tools:\nclaude mcp add --transport stdio flowkit -- flowkit-mcp --workspace /path/to/files --tools pdf,image" },
    desktop: { label: "Claude Desktop · claude_desktop_config.json", note: "Settings → Developer → Edit Config, then restart Claude", docs: "https://modelcontextprotocol.io/docs/develop/connect-local-servers",
      command: config("mcpServers") },
    codex: { label: "Codex CLI", note: "Verify with: codex mcp list", docs: "https://developers.openai.com/codex/mcp",
      command: "codex mcp add flowkit -- flowkit-mcp --workspace /path/to/files" },
    cursor: { label: "Cursor · .cursor/mcp.json", note: "Project file, or ~/.cursor/mcp.json for all projects", docs: "https://docs.cursor.com/context/model-context-protocol",
      command: config("mcpServers") },
    vscode: { label: "VS Code · .vscode/mcp.json", note: "Start the server from the MCP view or Copilot Chat", docs: "https://code.visualstudio.com/docs/copilot/chat/mcp-servers",
      command: config("servers", '\n      "type": "stdio",') },
    agy: { label: "Google Antigravity · .agents/mcp_config.json", note: "Open /mcp in Antigravity to check the connection", docs: "https://antigravity.google/docs/mcp/",
      command: config("mcpServers") },
  },
});

copyButton($("#copy-benchmark"), () => "npm run benchmark");

// ── Bind headline numbers ──
if (data) {
  const s = data.summary;
  const bind = {
    version: data.environment.flowkitVersion, date: data.generated,
    tools: data.fixedCost.find((f) => f.name === "all").tools,
    reduction: Math.round(s.averageReductionPercent), reductionPct: `${Math.round(s.averageReductionPercent)}%`, saved: s.averageSavedTokens,
    workflow: `${Math.round(s.workflowReduction[0])}–${Math.round(s.workflowReduction[1])}%`,
    fixedAll: fmt(s.allToolsFixedTokens), fixedOne: fmt(s.oneToolsetFixedTokens), fixedAllShort: compact(s.allToolsFixedTokens), fixedOneShort: compact(s.oneToolsetFixedTokens),
    breakEven: `${s.breakEvenOneToolset.join("–")} tasks`, breakEvenAll: s.breakEvenAll,
    passed: `${s.toolsPassed} / ${s.toolsRun}`, boundaries: s.boundariesBlocked, median: s.medianToolMs ? ms(s.medianToolMs) : "—",
  };
  document.querySelectorAll("[data-bind]").forEach((el) => { const v = bind[el.dataset.bind]; if (v !== undefined) el.textContent = v; });
}

// ── Tool groups ──
const groupInfo = {
  core: { title: "Always on", desc: "List files, read bounded text, inspect metadata.", tag: "core" },
  document: { title: "Documents", desc: "Pandoc conversions, Markdown cleanup, DOCX merging.", tag: "--tools document" },
  pdf: { title: "PDF", desc: "qpdf page operations, Ghostscript size reduction, AES-256, signatures.", tag: "--tools pdf" },
  image: { title: "Images", desc: "ImageMagick resize, crop, rotate, flip, filters, PNG/JPEG.", tag: "--tools image" },
  audio: { title: "Audio", desc: "FFmpeg convert, trim, volume, fade, loudness normalization.", tag: "--tools audio" },
  video: { title: "Video", desc: "FFmpeg trim, convert, resize, rotate, flip, mute, extract audio.", tag: "--tools video" },
};
function renderToolGroups() {
  const container = $("#tool-groups");
  if (!container || !data?.latency) return;
  const groups = {};
  for (const row of data.latency.rows) {
    const name = short(row.tool.replace(/ \(.*\)$/, ""));
    (groups[row.group] ||= new Set()).add(name);
  }
  container.innerHTML = Object.keys(groupInfo).filter((g) => groups[g]).map((g) => `
    <article class="tool-group">
      <header><h3>${groupInfo[g].title}</h3><code>${groupInfo[g].tag}</code></header>
      <p>${groupInfo[g].desc}</p>
      <ul>${[...groups[g]].map((t) => `<li><code>${esc(t)}</code></li>`).join("")}</ul>
    </article>`).join("");
}

// ── Modal ──
const modal = $("#test-results-modal");
function switchModalTab(tab) {
  document.querySelectorAll(".modal-tab-btn").forEach((b) => b.classList.toggle("active", b.dataset.modalTab === tab));
  document.querySelectorAll(".modal-tab-panel").forEach((p) => p.classList.toggle("active", p.id === `modal-tab-${tab}`));
}
function openModal(tab = "charts") {
  if (!modal) return;
  modal.classList.add("open"); modal.setAttribute("aria-hidden", "false");
  document.body.style.overflow = "hidden"; switchModalTab(tab);
  $("#close-modal-btn")?.focus();
}
function closeModal() {
  if (!modal) return;
  modal.classList.remove("open"); modal.setAttribute("aria-hidden", "true"); document.body.style.overflow = "";
}
document.querySelectorAll(".open-results-modal-btn").forEach((b) => b.addEventListener("click", (e) => { e.preventDefault(); openModal(b.dataset.targetTab || "charts"); }));
$("#close-modal-btn")?.addEventListener("click", closeModal);
modal?.addEventListener("click", (e) => { if (e.target === modal) closeModal(); });
window.addEventListener("keydown", (e) => { if (e.key === "Escape" && modal?.classList.contains("open")) closeModal(); });
document.querySelectorAll(".modal-tab-btn").forEach((b) => b.addEventListener("click", () => switchModalTab(b.dataset.modalTab)));

const groupLabels = { all: "All", core: "Core", document: "Documents", pdf: "PDF", image: "Images", audio: "Audio", video: "Video" };
const barClass = { core: "bar-teal", document: "bar-purple", pdf: "bar-purple", image: "bar-blue", audio: "bar-orange", video: "bar-orange" };

function renderModal() {
  if (!data) return;
  const s = data.summary, lat = data.latency;
  $("#modal-subtitle").textContent = lat ? `${s.toolsRun} tool runs · ${lat.runs} calls each · ${s.boundariesBlocked} safety checks · ${data.environment.os}` : "";
  $("#summary-cards").innerHTML = [
    [`${s.toolsPassed} / ${s.toolsRun}`, "Tool runs passed", s.toolsSkipped ? `${s.toolsSkipped} skipped (optional engine missing)` : "No skips"],
    [s.boundariesBlocked, "Safety checks blocked", "Path escapes, bad options, missing files"],
    [s.medianToolMs ? ms(s.medianToolMs) : "—", "Median tool call", "Including engine start-up"],
    [lat ? ms(lat.startupMs) : "—", "Server start-up", "Spawn, connect, list tools"],
  ].map(([v, l, sub]) => `<div class="summary-card"><div class="summary-card-val">${esc(v)}</div><div class="summary-card-label">${esc(l)}</div><div class="summary-card-sub">${esc(sub)}</div></div>`).join("");

  $("#engine-items").innerHTML = Object.entries(data.environment.engines).map(([name, version]) => `
    <div class="engine-item"><div class="engine-item-head"><span class="engine-indicator ${version === "not installed" ? "status-warn" : "status-ok"}"></span><strong>${esc(name)}</strong></div>
    <p class="engine-item-desc">${esc(String(version).slice(0, 60))}</p></div>`).join("") +
    `<div class="engine-item"><div class="engine-item-head"><strong>Machine</strong></div><p class="engine-item-desc">${esc(data.environment.cpu)} · ${data.environment.memoryGiB} GiB · Node ${esc(data.environment.node)}</p></div>`;

  // Latency chart with group filters.
  let filter = "all";
  const groups = ["all", ...new Set(lat?.rows.map((r) => r.group) ?? [])];
  $("#chart-controls").innerHTML = groups.map((g) => `<button class="chart-filter-btn${g === "all" ? " active" : ""}" data-chart-filter="${g}">${groupLabels[g] || g}</button>`).join("");
  const drawLatency = () => {
    const rows = (lat?.rows ?? []).filter((r) => r.status === "pass" && (filter === "all" || r.group === filter)).sort((a, b) => a.medianMs - b.medianMs);
    const max = Math.max(...rows.map((r) => r.medianMs), 1);
    $("#latency-bars-container").innerHTML = `<div class="latency-chart-list">${rows.map((r) => `
      <div class="latency-row" title="${esc(r.tool)}: ${ms(r.medianMs)} (${esc(r.engine)})">
        <span class="latency-label"><code>${esc(short(r.tool))}</code></span>
        <div class="latency-track"><div class="latency-fill ${barClass[r.group] || "bar-purple"}" style="width:${Math.max(2, (r.medianMs / max) * 100)}%"></div></div>
        <span class="latency-val">${ms(r.medianMs)}</span>
      </div>`).join("")}</div>`;
  };
  document.querySelectorAll("[data-chart-filter]").forEach((b) => b.addEventListener("click", () => {
    document.querySelectorAll("[data-chart-filter]").forEach((x) => x.classList.toggle("active", x === b));
    filter = b.dataset.chartFilter; drawLatency();
  }));
  drawLatency();

  // Test matrix.
  const matrix = [
    ...(lat?.rows ?? []).map((r) => ({ name: short(r.tool), group: r.group, status: r.status, time: r.status === "skipped" ? "—" : ms(r.medianMs), engine: r.engine, result: r.summary || "" })),
    ...(lat?.boundaries ?? []).map((b) => ({ name: b.check, group: "safety", status: b.blocked ? "pass" : "fail", time: ms(b.ms), engine: short(b.tool), result: b.message })),
  ];
  let tableFilter = "all", query = "";
  const tableGroups = ["all", ...new Set(matrix.map((m) => m.group))];
  $("#table-filters").innerHTML = tableGroups.map((g) => `<button class="pill-btn${g === "all" ? " active" : ""}" data-table-filter="${g}">${g === "safety" ? "Safety" : groupLabels[g] || g} (${g === "all" ? matrix.length : matrix.filter((m) => m.group === g).length})</button>`).join("");
  const statusPill = (s) => `<span class="status-pill status-${s === "pass" ? "pass" : s === "skipped" ? "optional" : "fail"}">${s === "pass" ? "✓ Pass" : s === "skipped" ? "Skipped" : "✕ Fail"}</span>`;
  const drawTable = () => {
    const list = matrix.filter((m) => (tableFilter === "all" || m.group === tableFilter) && (!query || `${m.name} ${m.engine} ${m.result}`.toLowerCase().includes(query)));
    $("#test-results-tbody").innerHTML = list.length ? list.map((m) => `<tr><td><strong><code>${esc(m.name)}</code></strong></td><td><span class="cat-pill">${esc(m.group)}</span></td><td>${statusPill(m.status)}</td><td><span class="time-cell">${m.time}</span></td><td><span class="engine-tag">${esc(m.engine)}</span></td><td class="desc-cell">${esc(m.result)}</td></tr>`).join("")
      : `<tr><td colspan="6" class="empty-table-msg">No results match.</td></tr>`;
  };
  document.querySelectorAll("[data-table-filter]").forEach((b) => b.addEventListener("click", () => {
    document.querySelectorAll("[data-table-filter]").forEach((x) => x.classList.toggle("active", x === b));
    tableFilter = b.dataset.tableFilter; drawTable();
  }));
  $("#table-search")?.addEventListener("input", (e) => { query = e.target.value.trim().toLowerCase(); drawTable(); });
  drawTable();

  // Tokens.
  $("#token-subtitle").textContent = `Own script vs one FlowKit call. Average ${s.averageReductionPercent}% fewer tokens (${s.averageSavedTokens} saved per task).`;
  const max = Math.max(...data.singles.map((r) => r.ownTokens));
  $("#token-comparison-bars").innerHTML = data.singles.map((r) => `
    <div class="token-row"><span class="token-task-name">${esc(r.label)}</span>
      <div class="token-bars-duo">
        <div class="token-subrow"><span class="token-sublabel">Own script</span><div class="token-bar-track"><div class="token-fill token-fill-baseline" style="width:${(r.ownTokens / max) * 100}%"></div></div><span class="token-subval">${fmt(r.ownTokens)}</span></div>
        <div class="token-subrow"><span class="token-sublabel">FlowKit</span><div class="token-bar-track"><div class="token-fill token-fill-flowkit" style="width:${(r.mcpTokens / max) * 100}%"></div></div><span class="token-subval"><strong>${fmt(r.mcpTokens)}</strong> <span class="badge-saving">−${r.reductionPercent}%</span></span></div>
      </div></div>`).join("");
  $("#session-tbody").innerHTML = data.sessions.map((r) => `<tr><td>${r.tasks}</td><td>${fmt(r.ownScripts)}</td><td>${fmt(r.mcpAllTools)}</td><td>${fmt(r.mcpOneToolset)}</td></tr>`).join("");
}

renderToolGroups();
renderModal();
